#!/usr/bin/env python3
"""
Attrium All-in-One Unified Bind, Persistent Module Binds & config/acc.json Fixer (Fabric 1.21.11)
Includes ClientThemeManager.java, FriendManager.java, HudManager.java, and GlassClickGuiScreen.java.
"""
import base64
import os
import re
import sys

FILES_B64 = {
    "attrium/ru/manager/ClientThemeManager.java": "",
    "attrium/ru/manager/FriendManager.java": "",
    "attrium/ru/manager/HudManager.java": "",
    "attrium/ru/screens/GlassClickGuiScreen.java": "",

}


def patch_duplicate_clickgui_openers(src_root):
    skip_files = {
        "GlassClickGuiScreen.java",
        "ClientThemeManager.java",
        "HudManager.java",
        "FriendManager.java",
        "ElytraTarget.java",
        "MaceTarget.java",
    }
    for root, _, files in os.walk(src_root):
        for fn in files:
            if not fn.endswith(".java") or fn in skip_files:
                continue
            path = os.path.join(root, fn)
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                src = f.read()
            orig = src
            if "new GlassClickGuiScreen(" in src:
                src = re.sub(r"new\s+GlassClickGuiScreen\s*\(\s*\)", "GlassClickGuiScreen.getInstance()", src)
            if "GlassClickGuiScreen" in src and ("GLFW_KEY_RIGHT_SHIFT" in src or "wasPressed" in src or "consumeClick" in src or "isKeyDown" in src):
                src = re.sub(
                    r"(\b(?:mc|client|Minecraft\.getInstance\(\))\.setScreen\s*\(\s*GlassClickGuiScreen\.getInstance\(\)\s*\)\s*;)",
                    r"/* unified in GlassClickGuiScreen: \1 */",
                    src,
                )
            if src != orig:
                with open(path, "w", encoding="utf-8") as f:
                    f.write(src)
                print(f"[UNIFIED] Patched duplicate ClickGUI opener in {os.path.relpath(path, src_root)}")


def main():
    cwd = os.getcwd()
    src_root = os.path.join(cwd, "src", "main", "java")
    if not os.path.isdir(src_root):
        print(f"[ERROR] Run this script from your project root (missing {src_root}).")
        sys.exit(1)
    for rel_path, b64_data in FILES_B64.items():
        out_path = os.path.join(src_root, *rel_path.split("/"))
        os.makedirs(os.path.dirname(out_path), exist_ok=True)
        with open(out_path, "wb") as f:
            f.write(base64.b64decode(b64_data))
        print(f"[OK] Wrote {rel_path}")
    patch_duplicate_clickgui_openers(src_root)
    print("\nAll 4 files installed! Run: ./gradlew build --no-daemon")


if __name__ == "__main__":
    main()